flange_w   = 10;   // flange width (Y)
flange_t   = 2.5;  // flange thickness (Z)
neck_w     = 6;    // neck width (Y)
neck_h     = 6.5;  // neck height above flange top (Z)
len        = 10;   // part length along X
screw_d    = 3.4;  // central screw hole diameter
eps        = 0.5;  // cutter overshoot

$fn = 64;

