    union() {
        // flange
        translate([-len/2, -flange_w/2, 0]) cube([len, flange_w, flange_t]);
        // neck
        translate([-neck_w/2, 0, flange_t]) cube([neck_w, len, neck_h]);
    }
    // through hole
    translate([0, 0, -eps]) cylinder(d = screw_d, h = total_h + 2*eps);
}
