```openscad
// Stiffened cover panel: flat plate with 4 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 120;   // plate length along X
plate_wid      = 50;    // plate width along Y
plate_thk      = 3;     // plate thickness (z = 0 to 3)

rib_thk        = 2;     // rib thickness along X
rib_h          = 5;     // rib height above plate (z = 3 to 8)
rib_count      = 4;     // number of ribs
rib_pitch      = 24;    // centre-to-centre spacing of ribs
rib_offset     = 24;    // centre of outer rib from plate end

rib_overlap    = 0.01;  // small overlap so ribs fuse into the plate

$fn = 64;

// ---------------- Derived ----------------
plate_x0 = -plate_len / 2;              // plate left end
plate_x1 = plate_len / 2;               // plate right end

// Check: 4 ribs, 24 mm pitch -> 3*24 = 72 mm span between outer rib centres.
// With 24 mm end offsets, total length needed = 24 + 72 + 24 = 120 mm. Matches plate.

// ---------------- Model ----------------
union() {
    // Base plate
    translate([plate_x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on their respective X positions, running full width along Y
    for (i = [0 : rib_count - 1]) {
        rib_x = i * rib_pitch + rib_offset - rib_thk / 2;
        translate([rib_x, -plate_wid / 2 - rib_overlap, plate_thk])
            cube([rib_thk, plate_wid + 2 * rib_overlap, rib_h]);
    }
}
```

