// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 12;   // Z position of the sphere centre (0, 0, 12)

handle_width        = 12;   // handle width (Y)
handle_thickness    = 3;    // handle thickness (Z)
handle_top_z        = 9;    // handle top face Z (flush with lower part of rim)
handle_start_x      = 10;   // handle start position (X)
handle_end_x        = 92;   // handle end position (X)

cut_extra           = 0.5;  // overshoot for clean boolean cuts
$fn                 = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Hollow spherical bowl: lower half only
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Straight flat handle
        translate([handle_start_x, -handle_width / 2, handle_top_z])
            cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere, leaving the rim at z = 12
    translate([0, 0, bowl_centre + cut_extra])
        sphere(r = bowl_outer_radius - bowl_wall_thickness);
}
