// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = [0, 0, 12]; // centre of the full sphere
handle_width        = 12;   // handle width (Y)
handle_thickness    = 3;    // handle thickness (Z)
handle_x_start      = 10;   // handle start (X)
handle_x_end        = 92;   // handle end (X)
cut_extra           = 0.5;  // overshoot of cutting shapes past faces

$fn = 96;                   // curve resolution

// Derived
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
rim_z             = bowl_centre[2] + bowl_outer_radius;  // z = 12
handle_top_z      = rim_z - handle_thickness;            // z = 9

// ---------------- Model ----------------
difference() {
    union() {
        // Spherical bowl (full sphere, lower half kept by the cut below)
        translate(bowl_centre)
            sphere(r = bowl_outer_radius);

        // Flat handle, centred on y = 0
        translate([handle_x_start, -handle_width / 2, handle_top_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut away the upper half of the sphere, leaving the lower half (z <= 12)
    translate(bowl_centre)
        cylinder(r = bowl_outer_radius, h = bowl_outer_radius + 0.01);

    // Through-hole along +X near the bowl rim for pouring / cleaning
    translate([bowl_centre[0] + 8, 0, rim_z - 2])
        cylinder(r = 4, h = (handle_x_end - handle_x_start) + 0.01);
}
