// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending to +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 12;   // Z position of the sphere centre (0, 0, 12)

handle_width        = 8;    // handle width along Y
handle_thickness    = 4;    // handle thickness along Z (top face flush with rim)
handle_x_start      = 10;   // handle start position along X
handle_x_end        = 112;  // handle end position along X

cut_overlap         = 0.5;  // extra length of cutters past the faces they cut
$fn                 = 96;   // curve resolution

// ---------------- Derived ----------------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness; // 10 mm
rim_z             = bowl_centre + bowl_outer_radius;        // 24 mm (top of bowl)
handle_top_z      = bowl_centre + handle_thickness;         // 16 mm

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half only, open upward
    difference() {
        sphere(r = bowl_outer_radius, d = 2 * bowl_outer_radius, $fn = 128);
        translate([0, 0, bowl_centre - cut_overlap])
            sphere(r = bowl_inner_radius, d = 2 * bowl_inner_radius, $fn = 128);
    }

    // Flat handle running along +X, centred on y = 0
    translate([handle_x_start, -handle_width / 2, handle_top_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
