// ---------- Model ----------
difference() {
    // Solid body
    translate([-total_len/2, -grip_width/2, 0])
        cube([total_len, grip_width, thickness]);

    // Cut out gauge and transition regions, leaving the two grip blocks
    for (s = [-1, 1]) {
        x0 = -total_len/2 + s * grip_length;
        x1 = x0 + transition_len;
        y0 = -grip_width/2;
        y1 = grip_width/2;
        translate([x0, y0, -eps])
            linear_extrude(height = thickness + 2*eps)
                polygon([[x0, y0], [x1, y0], [x1, y1], [x0, y1]]);
    }
