grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge

// Derived
grip_start_x   = -total_length/2 + grip_length;  // grip start (negative X)
gauge_start_x  = grip_start_x + transition_len;  // gauge start
gauge_end_x    = gauge_start_x + gauge_length;   // gauge end
grip_end_x     = gauge_end_x + transition_len;   // second grip start
specimen_end_x = grip_end_x + grip_length;       // overall end (positive X)

// Cutting overlap
eps = 0.5;

difference() {
    // Main body
    translate([-total_length/2, -grip_width/2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out gauge and transitions, leaving grip sections
    for (s = [-1, 1]) {
        x0 = grip_start_x * s;
        x1 = gauge_end_x * s;
        translate([x0 - eps, -grip_width/2 - eps, -eps])
            linear_extrude(height = thickness + 2*eps)
                polygon([[-eps, -grip_width/2 - eps], [eps, -grip_width/2 - eps],
                         [x1 - x0, 0], [eps, grip_width/2 + eps], [-eps, grip_width/2 + eps]]);
