grip_x0        = -total_length/2 + grip_length;   // left grip start X
gauge_x0       = grip_x0 + grip_length;           // gauge start X
gauge_x1       = gauge_x0 + gauge_length;         // gauge end X
right_x0       = gauge_x1 + transition_len;       // right grip start X
// check: right_x0 + grip_length = total_length/2 + grip_length = 150 - 35 = 115

// ---------- Model ----------
difference() {
    // Solid body: union of grip, gauge and transition blocks
    union() {
        for (sx = [-1, 1]) {
            translate([sx * grip_x0, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        for (sx = [-1, 1]) {
            translate([sx * right_x0, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
        }
    }

    // Cut the two transition regions so their widths change linearly
    // from grip_width to gauge_width over transition_len
    for (sx = [-1, 1]) {
        x0 = sx * (grip_x0 + grip_length);   // transition start X
        x1 = x0 + transition_len;             // transition end X
        // y(x) = gauge_width + (grip_width - gauge_width) * (x - x0)/transition_len
        translate([x0 - eps, -grip_width/2, 0])
            linear_extrude(thickness + 2*eps)
                polygon([[-transition_len/2 - eps, -grip_width/2 - eps],
                         [-transition_len/2 - eps,  grip_width/2 + eps],
                         [transition_len/2 + eps,  grip_width/2 + eps],
                         [transition_len/2 + eps,  -grip_width/2 - eps]]);
        // rotate 90 so the same trapezoid runs along X with the correct slope
        translate([x0 - eps, -grip_width/2, 0])
            rotate([0, 90, 0])
                linear_extrude(thickness + 2*eps)
                    polygon([[-transition_len/2 - eps, -grip_width/2 - eps],
                             [-transition_len/2 - eps,  grip_width/2 + eps],
                             [transition_len/2 + eps,  grip_width/2 + eps],
                             [transition_len/2 + eps,  -grip_width/2 - eps]]);
    }
