rim_i_d = wheel_d - 2 * rim_width;   // inner diameter of rim ring
spoke_h = wheel_thick;               // spokes run full height

// ---------- Model ----------
union() {
    // Outer rim ring
    difference() {
        cylinder(d = wheel_d, h = rim_width);
        translate([0, 0, -eps])
            cylinder(d = rim_i_d, h = rim_width + 2 * eps);
    }

    // Central hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_thick);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_thick + 2 * eps);
    }

    // Radial spokes, evenly spaced
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([0, 0, -eps])
            linear_extrude(height = spoke_h + 2 * eps)
                polygon([[-hub_d / 2, 0], [hub_d / 2, 0],
                          [hub_d / 2, spoke_d], [-hub_d / 2, spoke_d]]);
        // shift polygon so first spoke lies on +X axis
        rotate([0, 0, a])
            translate([rim_i_d / 2 - spoke_d / 2, 0, -eps])
                linear_extrude(height = spoke_h + 2 * eps)
                    polygon([[0, 0], [spoke_d, 0], [spoke_d, spoke_d], [0, spoke_d]]);
    }
}
