// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom touching the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 12;   // Z position of the sphere centre (0, 0, 12)
handle_width        = 10;   // handle width (Y)
handle_thickness    = 4;    // handle thickness (Z)
handle_x_start      = 10;   // handle start position (X)
handle_x_end        = 112;  // handle end position (X)
cut_extra           = 0.5;  // overshoot for clean boolean cuts

$fn = 96;

// ---------------- Model ----------------
difference() {
    union() {
        // Spherical bowl (full sphere)
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Flat handle, top face flush with the rim (z = 8 to 12)
        translate([handle_x_start, -handle_width / 2,
                   bowl_centre - handle_thickness])
            cube([handle_x_end - handle_x_start,
                  handle_width,
                  handle_thickness]);
    }

    // Lower half of the bowl: cut along the equatorial plane, keeping the bottom
    translate([0, 0, bowl_centre - cut_extra])
        cube([bowl_outer_radius + cut_extra,
              bowl_outer_radius + cut_extra,
              cut_extra]);

    // Small hole at the bottom so the solid touches the bed at z = 0
    translate([0, 0, -1])
        cylinder(r = 1);
}
