// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X
plate_wid   = 20;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

knuckle_d   = 6;     // knuckle (cylinder) diameter
knuckle_z   = 3;     // knuckle axis height (Z)
knuckle_y   = 10;    // knuckle axis Y position (+Y edge)
knuckle_n   = 5;     // number of segments along plate length
knuckle_pitch = plate_len / knuckle_n; // 10 mm segment length
knuckle_hole_d = 3;  // pin hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (0-indexed: 0, 2, 4)
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([-plate_len/2 + i * knuckle_pitch - knuckle_d/2,
                           knuckle_y - knuckle_d/2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + eps);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([-plate_len/2 + i * knuckle_pitch - knuckle_pitch/2 - eps,
                           knuckle_y,
                           knuckle_z])
                    translate([knuckle_pitch/2 + eps, 0, 0])
                        cylinder(d = knuckle_hole_d, h = plate_thk + 2 * eps);
            }
    }
}
