shaft_d       = 5;     // shaft hole diameter
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
union() {
    // Disc, centred at z = 0, shifted in X
    difference() {
        cylinder(d = disc_d, h = disc_t);
        translate([disc_x, 0, -eps])
            cylinder(d = shaft_d, h = disc_t + 2 * eps);   // shaft hole through disc
    }

    // Hub, centred on shaft axis, rising from z = disc_t to z = disc_t + hub_h
    difference() {
        translate([0, 0, disc_t])
            cylinder(d = hub_d, h = hub_h + 0.01);         // tiny overlap into disc for clean union
        translate([0, 0, -eps])
            cylinder(d = shaft_d, h = hub_h + 1 + 2 * eps); // shaft hole through hub
    }
}
