trans_x1       = trans_x0 + transition_len;       // transition end X
grip_x1        = trans_x1 + transition_len;       // right grip start X
check          = grip_x1 + grip_length;           // should equal +total_length/2

// ---------- Model ----------
difference() {
    // Solid body
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon([[-total_length/2, -grip_width/2], [-total_length/2, grip_width/2],
                     [check, grip_width/2], [check, -grip_width/2]]);

    // Cutters for grip and gauge regions (extends past end faces)
    union() {
        // Left grip
        translate([grip_x0 - eps, -grip_width/2 - eps, -eps])
            linear_extrude(thickness + 2*eps)
                circle(d = grip_width, $fn = 96);
        // Right grip
        translate([grip_x1, -grip_width/2 - eps, -eps])
            linear_extrude(thickness + 2*eps)
                circle(d = grip_width, $fn = 96);
