                    [transition_length, transition_end_w / 2], [0, transition_start_w / 2]
                ]);
        translate([grip_length + transition_length, 0, 0])
            linear_extrude(specimen_thickness)
                polygon([
                    [0, -transition_start_w / 2], [transition_length, -transition_end_w / 2],
                    [transition_length, transition_end_w / 2], [0, transition_start_w / 2]
                ]);
