    translate([-total_length / 2 - cut_extra, 0, 0])
        linear_extrude(cut_extra)
            rectangle([cut_extra * 2, grip_width]);
    translate([total_length / 2 - cut_extra, 0, 0])
        linear_extrude(cut_extra)
