        cube([total_length, grip_width, thickness]);

    // Cut out the gauge section (narrow middle)
    translate([-total_length/2 + grip_length + transition_len,
                -gauge_width/2, -eps])
        cube([gauge_length, gauge_width, thickness + 2*eps]);

    // Cut out the grip sections at each end, leaving the transitions
    for (s = [-1, 1]) {
        x0 = -total_length/2 + (s > 0 ? grip_length : -grip_length);
        translate([x0, -grip_width/2, -eps])
            cube([grip_length, grip_width, thickness + 2*eps]);
    }
}
