// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
gauge_x0 = -total_length/2 + grip_length + transition_len;       // gauge start X
gauge_x1 = gauge_x0 + gauge_length;                               // gauge end X

difference() {
    // Main body: two grip blocks + two transition blocks + gauge block
    union() {
        for (side = [-1, 1]) {
            translate([side > 0 ? gauge_x1 + eps : gauge_x0 - eps, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);

            translate([side > 0 ? gauge_x1 : gauge_x0, -transition_len/2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len/2, -grip_width/2], [-transition_len/2, grip_width/2],
                              [transition_len/2, grip_width/2], [transition_len/2, -grip_width/2]]);
        }
        translate([gauge_x0 - eps, -gauge_width/2, 0])
            cube([gauge_length + 2*eps, gauge_width, thickness]);
    }

    // Central through-cut (keeps a solid core so the cut is not coplanar with faces)
    translate([gauge_x0 - eps, -gauge_width/2 - eps, -eps])
        cube([gauge_length + 2*eps, gauge_width + 2*eps, thickness + 2*eps]);
}
