// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to wheel_thickness

// ---------- Parameters ----------
wheel_thickness   = 5;     // rim, hub and spoke thickness (mm)
outer_diameter    = 60;    // outer rim diameter (mm)
rim_width         = 5;     // rim width from outer edge inward (mm)
hub_diameter      = 20;    // central hub diameter (mm)
axle_hole_d       = 5;     // through-hole diameter in hub (mm)
spoke_count       = 6;     // number of spokes (mm)
spoke_width       = 5;     // spoke width (mm)
spoke_start_angle = 0;     // first spoke along +X axis (degrees)
cut_overlap       = 0.5;   // extra length of cutters past faces (mm)

$fn = 128;

// ---------- Derived ----------
inner_diameter = outer_diameter - 2 * rim_width;   // ring inner diameter
spoke_length   = (outer_diameter / 2) - (rim_width + cut_overlap);

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = wheel_thickness);

        // Central hub with axle hole
        translate([0, 0, -cut_overlap])
            cylinder(d = hub_diameter, h = wheel_thickness + 2 * cut_overlap);

        // Spokes, evenly spaced, first along +X
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([hub_diameter / 2 + cut_overlap, 0, -cut_overlap])
                    cube([spoke_length, spoke_width, wheel_thickness + 2 * cut_overlap]);
        }
    }

    // Cut out the ring's inner area, leaving a smooth bore
    translate([0, 0, -cut_overlap])
        cylinder(d = inner_diameter, h = wheel_thickness + 2 * cut_overlap);

    // Clean up small overlaps between spokes and rim/hub
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
            translate([hub_diameter / 2 + cut_overlap, 0, -cut_overlap])
                cube([spoke_length + 0.01, spoke_width + 0.01, wheel_thickness + 2 * cut_overlap]);
    }
}
