    for (i = [0 : rib_count - 1]) {
        // X position of rib i, linearly spaced between rib_x0 and rib_xn
        rib_x = rib_x0 + i * rib_pitch;
        translate([rib_x - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
