        cylinder(r = bowl_outer_radius, h = 2 * bowl_outer_radius,
                 centre = [0, 0, bowl_centre_z]);

        // Flat handle, centred on y = 0, running along +X
        translate([handle_x_start, -handle_width / 2, handle_top_z - handle_thickness])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere above the rim (z > bowl_rim_z)
    translate([0, 0, bowl_rim_z])
        cylinder(r = bowl_outer_radius + cut_overlap, h = cut_overlap,
                 centre = [0, 0, cut_overlap / 2]);

    // Hollow out the bowl wall, leaving the lower half of the shell
    translate([0, 0, bowl_bottom_z])
        cylinder(r = bowl_outer_radius - bowl_wall_thickness,
                 h = bowl_bottom_z + bowl_wall_thickness + cut_overlap,
                 centre = [0, 0, bowl_bottom_z + bowl_wall_thickness / 2]);
}
