// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
x0    = -total_length / 2;              // left end X position

// ---- Outline builder ----
// X positions of the two grip/gauge boundaries
bound_x = grip_length + transition_len;

// Width of a point on the outline, given its X offset from the left end
function width(x) =
    if (x < bound_x)
        grip_width
    else if (x < bound_x + gauge_length)
        gauge_width
    else if (x < bound_x + gauge_length + transition_len)
        gauge_width + (grip_width - gauge_width) * (x - (bound_x + gauge_length)) / transition_len
    else
        grip_width;

difference() {
    // Solid body
    translate([x0, -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon([for (x = [0 : total_length]) [x, width(x) / 2]]);

    // Through-cut along X, centred on the gauge section
    translate([x0 + bound_x + gauge_length / 2 + eps, -gauge_width / 2, -eps])
        cube([gauge_length + 2 * eps, gauge_width + 2 * eps, thickness + 2 * eps]);
}
```

```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

$fn = 64;

// ---------- Derived ----------
grip_x0 = -total_length/2 + grip_length;        // left grip start X
grip_x1 = total_length/2 - grip_length;         // right grip start X
gauge_x0 = grip_x0 + grip_length + transition_len;  // gauge start X
gauge_x1 = gauge_x0 + gauge_length;              // gauge end X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (trapezoidal in Y)
        for (s = [-1, 1]) {
            x = grip_x0 + grip_length;              // transition start X
            dx = transition_len;                    // transition length
            w0 = grip_width;                        // width at start
            w1 = gauge_width;                       // width at end
            translate([x, -w0/2, 0])
                linear_extrude(thickness)
                    polygon([[-dx/2, -w0/2], [-dx/2, w0/2],
                              [dx/2, w1/2], [dx/2, -w1/2]]);
        }
    }

    // Small cutouts along X to avoid coplanar faces between sections
    for (x = [grip_x0 + grip_length, gauge_x0 + gauge_length])
        translate([x - 0.5, 0, -1])
            cube([1, thickness + 2, grip_width + 2]);
}
