        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (width changes linearly from grip to gauge)
        for (side = [-1, 1]) {
            x0 = -total_length/2 + grip_length;
            x1 = gauge_x0 + transition_length;
            w0 = grip_width;
            w1 = gauge_width;
            translate([x0, -w0/2, 0])
                linear_extrude([transition_length, thickness])
                    polygon([[-w0/2, w0/2], [w1/2 - side*0.0001, w1/2 + side*0.0001], [w1/2 + side*0.0001, -w1/2 - side*0.0001], [-w0/2, w0/2]]);
        }
    }
    // Small cutouts at each end to avoid coplanar faces
    translate([-total_length/2 - 0.5, -grip_width/2 - 0.5, -0.5])
        cube([0.5, grip_width + 1, thickness + 1]);
    translate([total_length/2 - grip_length, -grip_width/2 - 0.5, -0.5])
        cube([0.5, grip_width + 1, thickness + 1]);
