// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------------- Parameters ----------------
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// Derived
grip_start_x   = -total_length/2 + grip_length;  // left grip start X
gauge_start_x  = grip_start_x + transition_len;  // gauge start X
right_gauge_x   = total_length/2 - grip_length;  // right grip end X

// ---------------- Model ----------------
difference() {
    // Solid body: grip - transition - gauge - transition - grip
    union() {
        for (s = [-1, 1]) {
            translate([s * grip_start_x, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        translate([gauge_start_x, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        for (s = [-1, 1]) {
            translate([s * right_gauge_x, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
        }
    }

    // Cut the two transition regions so their widths change linearly
    for (s = [-1, 1]) {
        x0 = s * grip_start_x + transition_len;  // gauge start X (or mirror)
        // cylinder with $fn=64 runs along X; radius changes from
        // (grip_width - gauge_width)/2 at x0 to 0 at x0 + transition_len
        translate([x0 - 1, -grip_width/2, 0])
            cylinder(h = transition_len + 2,
                     r = (grip_width - gauge_width)/2,
                     $fn = 64);
    }
}
