// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to specimen thickness

// ---------------- Parameters ----------------
specimen_thickness   = 3;     // thickness (Z), mm
gauge_width          = 6;     // narrow gauge section width (Y), mm
gauge_length         = 30;    // gauge section length (X), mm
grip_width           = 15;    // grip section width (Y), mm
grip_length          = 30;    // grip section length (X), mm
transition_length    = 15;    // transition section length (X), mm
specimen_total_length = 120;  // overall length along X, mm
eps                  = 0.5;   // cutter overshoot past faces, mm

$fn = 64;

// Check: 2*grip + 2*transition + gauge = 2*15 + 2*15 + 30 = 90 mm
// (the remaining 30 mm is split between the two end faces)

// ---------------- Model ----------------
difference() {
    // Solid block, centred on origin in X and Y
    translate([-specimen_total_length/2, -grip_width/2, 0])
        cube([specimen_total_length, grip_width, specimen_thickness]);

    // Cut out the gauge section and the two transition sections
    // (from the top face, extended past the bottom face to avoid coplanar faces)
    for (s = [-1, 1]) {
        x0 = -specimen_total_length/2 + grip_length + s * transition_length;
        x1 = x0 + transition_length;
        y0 = (gauge_width + grip_width) / 2;              // outer edge of grip
        y1 = (gauge_width + grip_width + 2 * transition_length) / 2; // outer edge of transition
        translate([x0 - eps, y0 - eps, specimen_thickness/2])
            linear_extrude(height = specimen_thickness + 2 * eps)
                polygon([[x0 - eps, y0 - eps], [x1 + eps, y0 - eps],
                         [x1 + eps, y1 - eps], [x0 - eps, y1 - eps]]);
    }

