x_gauge      = total_length / 2 - gauge_length / 2;      // gauge centre X
x_transition = x_grip_in + transition_length;            // transition / end boundary

// Check: 2 * (grip_length + transition_length + gauge_length / 2)
// = 2 * (35 + 10 + 15) = 120 mm (matches total_length)

// ---------- Model ----------
difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, specimen_thickness]);

    // Cut out the gauge section and the two transition sections,
    // extended past the end faces to avoid coplanar faces
    for (x = [x_grip_in - cut_extra, x_gauge - gauge_length / 2 - cut_extra, x_transition + cut_extra]) {
        translate([x, -specimen_thickness / 2 - cut_extra, 0])
            cube([gauge_length, specimen_thickness + 2 * cut_extra, specimen_thickness + 2 * cut_extra]);
