    // Left grip / gauge
    translate([grip_x0 + grip_length - eps, -grip_width / 2 - eps, -eps])
        cube([transition_len + 2 * eps, grip_width + 2 * eps, thickness + 2 * eps]);

    // Right grip / gauge
    translate([total_length - grip_x0 - grip_length + eps, -grip_width / 2 - eps, -eps])
