// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// --- Dimensions (mm) ---
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// Derived: width change over transition (grip -> gauge)
width_change = gauge_width - grip_width;  // -14 mm

// Cutting overlap to avoid coplanar faces
eps = 0.5;

module specimen() {
    difference() {
        // Solid body: grip + transition + gauge + transition + grip
        union() {
            for (s = [-1, 1]) {
                translate([s * (total_length / 2 - grip_length - transition_len), 0, 0])
                    linear_extrude(thickness)
                        polygon([
                            [0, -grip_width / 2], [transition_len, -grip_width / 2 + width_change * transition_len / 30],
                            [transition_len, grip_width / 2 - width_change * transition_len / 30], [0, grip_width / 2]
                        ]);
            }
            translate([-total_length / 2 + grip_length + transition_len, 0, 0])
                linear_extrude(thickness)
                    rectangle([gauge_length, gauge_width]);
        }

        // End cutters, extended past faces
        translate([-total_length / 2 - eps, 0, -eps])
            linear_extrude(thickness + 2 * eps)
                rectangle([eps, total_length]);
        translate([total_length / 2 - gauge_length - transition_len - eps, 0, -eps])
            linear_extrude(thickness + 2 * eps)
                rectangle([eps, total_length]);
    }
}

specimen();
