        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_a + i * 360 / spoke_count;
            translate([spoke_r_start * cos(a), spoke_r_start * sin(a), 0])
                cube([spoke_w, (inner_d / 2 - spoke_r_start) + 1, thickness]); // +1 to overlap rim
        }
    }

