        // Outer rim
        cylinder(d = outer_d, h = rim_w);
        // Hub
        cylinder(d = hub_d, h = rim_w + 0.01); // slight overlap into rim for clean union
        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([hub_d / 2, 0, 0])
                    cube([spoke_w, spoke_w, spoke_t]);
