    difference() {
        cylinder(d = outer_d, h = rim_width);
        translate([0, 0, -eps])
            cylinder(d = rim_i_d, h = rim_width + 2 * eps);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_thickness + 2 * eps);
    }

    // Radial spokes
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([0, 0, -eps])
            linear_extrude(height = spoke_h + 2 * eps)
                polygon([[-hub_d / 2, 0], [hub_d / 2, 0],
                          [hub_d / 2, spoke_d], [-hub_d / 2, spoke_d]]);
    }
}
