// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 15;   // outer radius of the spherical bowl
bowl_wall_thickness = 1.5;  // thickness of the bowl wall
bowl_centre         = 15;   // Z position of the sphere centre (0, 0, 15)
bowl_rim_z          = 15;   // Z of the bowl rim (top of the lower half)
bowl_bottom_z       = 0;    // Z where the bowl bottom touches the bed

handle_width        = 10;   // handle width along Y
handle_thickness    = 4;    // handle thickness along Z (flush with rim: 11 to 15)
handle_start_x      = 13.5; // handle start X (overlaps the bowl rim)
handle_end_x        = 75;   // handle end X

cut_overlap         = 0.5;  // extra length of cutting shapes past faces
$fn                 = 96;   // curve resolution

// ---------------- Derived ----------------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness; // 13.5 mm
handle_top_z      = bowl_rim_z - handle_thickness;           // 11 mm
handle_bottom_z   = handle_top_z - handle_thickness;         // 7 mm

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half of a shell, open upward
    difference() {
        sphere(r = bowl_outer_radius, d = bowl_centre);
        translate([0, 0, bowl_centre + cut_overlap])
            sphere(r = bowl_inner_radius, d = cut_overlap);
    }
    // Keep only the lower half (z <= bowl_centre)
    clip_z(bowl_centre + 0.01);

    // Flat handle running along +X, centred on y = 0
    translate([handle_start_x, -handle_width / 2, handle_bottom_z])
        cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
}

// ---------------- Helpers ----------------
// Cut a solid at a given Z plane, keeping the lower part
clip_z(zc) {
    difference() {
        union() {
            // The solid itself (no holes yet)
            translate([min_bounding_x(), min_bounding_y(), min_bounding_z()])
                cube([max_bounding_x() - min_bounding_x(),
                      max_bounding_y() - min_bounding_y(),
                      max_bounding_z() - min_bounding_z()]);
        }
        // Cutting plane, extended past the top and bottom faces
        translate([min_bounding_x() - cut_overlap,
                   min_bounding_y() - cut_overlap,
                   zc])
            cube([max_bounding_x() + cut_overlap,
                  max_bounding_y() + cut_overlap,
                  cut_overlap]);
    }
}

// Bounding-box helpers for the clip_z plane
min_bounding_x() = -bowl_outer_radius;
min_bounding_y() = -bowl_outer_radius;
min_bounding_z() = bowl_bottom_z;
max_bounding_x() = handle_end_x;
max_bounding_y() = handle_width / 2;
max_bounding_z() = bowl_rim_z;
