// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height (above top face)
knuckle_n   = 3;    // number of knuckles
knuckle_pitch = (plate_len - 2 * knuckle_d) / (knuckle_n - 1); // 15 mm centre-to-centre

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past faces for clean differences

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge, axis along X at y = 10
        for (i = [0 : knuckle_n - 1]) {
            x = i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2;
