gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)
total_length   = 140;   // overall specimen length (X)

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// Derived: transition width change per unit X
w_per_x = (grip_width - gauge_width) / transition_len;

// ---------- Model ----------
difference() {
    // Solid block, centred on origin in X/Y, resting on z = 0
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out the two grip sections and the two transition sections
    for (s = [-1, 1]) {
        x0 = -total_length / 2 + grip_length;              // grip start X
        w0 = grip_width;                                   // grip width
        x1 = x0 + transition_len;                          // transition end X
        w1 = gauge_width + transition_len * w_per_x;       // gauge-side width
        x2 = x1 + gauge_length;                            // second grip start X
        w2 = grip_width;                                   // second grip width
        x3 = x2 + transition_len;                          // second transition end X
        w3 = w1;                                           // mirror: wider end of transition
        x4 = x3 + gauge_length;                            // overall end X

        linear_extrude(thickness + eps)
            polygon([
                [x0, -w0 / 2], [x0, w0 / 2],
                [x1, -w1 / 2], [x1, w1 / 2],
                [x2, -w2 / 2], [x2, w2 / 2],
                [x3, -w3 / 2], [x3, w3 / 2],
                [x4, -w4 / 2], [x4, w4 / 2]
            ]);
    }
