// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
total_length   = 150;   // overall specimen length (X)

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
grip_x0        = -total_length/2 + grip_length;   // left grip start X
gauge_x0       = grip_x0 + grip_length;           // gauge start X
gauge_x1       = gauge_x0 + gauge_length;         // gauge end X
right_x0       = gauge_x1 + transition_len;        // right grip start X
right_x1       = right_x0 + grip_length;          // right grip end X

// ---------- Model ----------
difference() {
    // Solid body: grip - transition - gauge - transition - grip
    union() {
        for (x0 = grip_x0 : transition_len : gauge_x0) {
            // left transition: width grows from grip to gauge
            translate([x0, -grip_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-grip_width/2, -grip_width/2], [-grip_width/2, grip_width/2],
                             [gauge_width/2, gauge_width/2], [gauge_width/2, -gauge_width/2]]);
        }
        translate([gauge_x0, -gauge_width/2, 0])
            linear_extrude(thickness)
                translate([-gauge_length/2, 0])
                    rectangle([gauge_length, gauge_width]);
        for (x0 = gauge_x1 + transition_len - grip_length : grip_length : right_x1) {
            // right transition: width shrinks from grip to gauge
            translate([x0, -grip_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-grip_width/2, -grip_width/2], [-grip_width/2, grip_width/2],
                             [gauge_width/2, gauge_width/2], [gauge_width/2, -gauge_width/2]]);
        }
    }

    // Cutters: two end blocks that leave the grip sections
    translate([-total_length/2 - eps, -grip_width/2 - eps, -eps])
        cube([total_length/2 - gauge_x0 - transition_len, grip_width + 2*eps, thickness + 2*eps]);
    translate([right_x0 + transition_len - gauge_x0, -grip_width/2 - eps, -eps])
        cube([grip_length + eps, grip_width + 2*eps, thickness + 2*eps]);
