// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to wheel_thickness

// ---------- Parameters ----------
wheel_d      = 60;   // outer rim diameter
rim_width    = 5;    // rim width (radial)
hub_d        = 14;   // hub diameter
axle_d       = 5;    // axle hole diameter
spoke_d      = 5;    // spoke width
spoke_count  = 4;    // number of spokes
spoke_start  = 0;    // angle of first spoke (deg, 0 = +X axis)
wheel_thickness = 6; // wheel thickness (Z)
eps          = 0.5;  // cutter overshoot past faces

$fn = 128;

// ---------- Derived ----------
rim_i_d = wheel_d - 2 * rim_width;  // inner diameter of rim (hub + wall)
spoke_h = wheel_thickness;          // spokes run full height

// ---------- Model ----------
union() {
    // Outer rim (ring)
    difference() {
        cylinder(d = wheel_d, h = rim_width);
        translate([0, 0, -eps])
            cylinder(d = rim_i_d, h = rim_width + 2 * eps);
    }

    // Central hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_thickness + 2 * eps);
    }

    // Straight spokes, evenly spaced
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start + i * 360 / spoke_count])
            translate([hub_d / 2 + 0.01, 0, -eps])
                cube([spoke_d, (wheel_d - hub_d) / 2 - 0.01, spoke_h]); // inner half
            translate([-hub_d / 2 - 0.01, 0, -eps])
                cube([spoke_d, (wheel_d - hub_d) / 2 - 0.01, spoke_h]); // outer half
    }
}
