// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 80;   // plate length along X
plate_wid      = 60;   // plate width along Y
plate_thk      = 3;    // plate thickness (z = 0 to 3)

rib_thk        = 3;    // rib thickness along X
rib_h          = 6;    // rib height above plate (z = 3 to 9)
rib_count      = 3;    // number of ribs

rib_pitch      = 20;   // centre-to-centre spacing of ribs
rib_offset     = 20;   // centre of outer rib from nearest plate end

eps            = 0.5;  // overcut so cutters pass through faces cleanly
$fn            = 64;   // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_topp     = plate_thk + rib_h;  // top of plate / bottom of ribs (z = 6)
rib_top        = plate_topp + rib_h; // top of ribs (z = 9)
x0             = -plate_len / 2;    // plate left end
x1             = plate_len / 2;     // plate right end

// ---------------- Model ----------------
union() {
    // Base plate
    translate([x0, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on their 20 mm pitch grid
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch - (rib_count - 1) * rib_pitch / 2;
        // Keep outer ribs at the specified offset from the plate ends
        if (i == 0 || i == rib_count - 1)
            x_c = x0 + rib_offset;
        translate([x_c - rib_thk / 2, -plate_wid / 2, plate_topp])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
