// Stiffened cover panel: flat plate with 4 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X
plate_wid   = 80;    // plate width along Y
plate_thk   = 3;     // plate thickness (z = 0 to 3)

rib_thk     = 2;     // rib thickness along X
rib_h       = 4;     // rib height above plate (z = 3 to 7)
rib_pitch   = 16;    // centre-to-centre spacing of ribs along X
rib_count   = 4;     // number of ribs

eps         = 0.5;   // overcut so cutters pass beyond faces
$fn         = 64;    // circle resolution (no curves here, set per rules)

// Derived: distance from plate end to the centre of the outer rib
end_offset  = rib_pitch / 2;   // 16 mm, as specified

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, standing on the plate
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch + end_offset;   // rib centre X position
        translate([x_c - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
