// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 10;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 10;   // Z position of the sphere centre (0, 0, 10)
bowl_rim_z          = 10;   // Z height of the bowl rim (lower half, so z = centre_z)
bowl_bottom_z       = 0;    // Z height of the bowl bottom (touches the bed)

handle_width        = 10;   // handle width along Y
handle_thickness    = 4;    // handle thickness along Z
handle_top_z        = 6;    // handle top face Z (flush with rim: 6 to 10)
handle_x_start      = 8;    // handle start along X
handle_x_end        = 90;   // handle end along X

cut_overlap         = 0.5;  // extra length of cutters past the faces they cut
$fn                 = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Hollow spherical bowl: lower half of a shell
        difference() {
            sphere(r = bowl_outer_radius, d = bowl_centre - bowl_outer_radius);
            translate([0, 0, bowl_centre - bowl_wall_thickness])
                sphere(r = bowl_outer_radius - 2 * bowl_wall_thickness,
                       d = bowl_centre - bowl_outer_radius - 2 * bowl_wall_thickness);
        }
        // Flat handle, centred on y = 0, top face flush with rim
        translate([handle_x_start, -handle_width / 2, handle_top_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the bowl along the equator, keeping only the lower half
    translate([0, 0, bowl_rim_z + cut_overlap])
        cylinder(r = bowl_outer_radius + cut_overlap, h = cut_overlap);

    // Clean up the handle end face (coplanar with the rim)
    translate([handle_x_end - cut_overlap, -handle_width / 2, handle_top_z])
        cube([cut_overlap + 0.01, handle_width, handle_thickness]);
}
