// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
total_length   = 140;   // overall specimen length (X)

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
grip_x0        = -total_length/2 + grip_length;   // left grip start X
gauge_x0       = grip_x0 + grip_length;           // gauge start X
trans_x0       = gauge_x0 + gauge_length;         // transition start X
trans_x1       = trans_x0 + transition_len;       // transition end X (right)
trans_x2       = total_length - trans_x1;         // left transition end X
grip_x1        = trans_x2 - transition_len;        // right grip start X

// ---------- Model ----------
difference() {
    // Solid body
    translate([-total_length/2, -grip_width/2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out gauge and transitions, leaving grip sections
    for (sx = [-1, 1]) {
        x0 = sx < 0 ? grip_x0 : grip_x1;
        x1 = x0 + gauge_length + 2*transition_len;
        w0 = grip_width;
        w1 = gauge_width;
        translate([x0 - eps, -grip_width/2 - eps, 0])
            linear_extrude(thickness + 2*eps)
                polygon([[-eps, -eps], [x1 - x0 + eps, -eps],
                         [x1 - x0 + eps, w0 + 2*eps], [-eps, w0 + 2*eps]]);
    }
}
