// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---------------- Parameters ----------------
specimen_thickness   = 3;     // thickness along Z (mm)
total_length         = 130;   // overall length along X (mm)
gauge_width          = 8;     // gauge section width (Y) (mm)
gauge_length         = 40;    // gauge section length (X) (mm)
grip_width           = 15;    // grip section width (Y) (mm)
grip_length          = 35;    // grip section length (X) (mm)
transition_length    = 10;    // transition section length (X) (mm)
transition_start_w   = 15;    // transition width near grip (Y) (mm)
transition_end_w     = 8;     // transition width near gauge (Y) (mm)
cut_extra            = 0.5;   // overshoot of cutters past faces (mm)

$fn = 64;

// ---------------- Derived ----------------
// X positions of section boundaries, centred on origin
grip_in_x     = total_length / 2 - grip_length - transition_length;
gauge_start_x = grip_in_x + grip_length;
gauge_end_x   = gauge_start_x + gauge_length;
grip_out_x    = gauge_end_x + transition_length;

// ---------------- Model ----------------
difference() {
    // Solid block covering full length and grip width
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, specimen_thickness]);

    // Central gauge section, overcut at ends
    translate([gauge_start_x - cut_extra, -gauge_width / 2, 0])
        cube([gauge_length + 2 * cut_extra, gauge_width, specimen_thickness]);

    // Two transition sections, width changes linearly along X
    for (s = [-1, 1]) {
        x0 = grip_in_x + s * transition_length / 2;
        x1 = x0 + s * transition_length;
        // scale_y = 1 at grip end, = gauge_width/transition_start_w at gauge end
        translate([x0, -transition_start_w / 2, 0])
            cube([transition_length,
                  transition_start_w * (1 - s * 0.5 * (1 - gauge_width / transition_start_w)),
                  specimen_thickness]);
    }
}
