outer_d        = 100;   // outer rim diameter (mm)
rim_width      = 5;     // rim width (mm)
hub_d          = 14;    // hub diameter (mm)
axle_d         = 8;     // centre axle hole diameter (mm)
spoke_count    = 8;     // number of spokes
spoke_w        = 5;     // spoke width (mm)
spoke_start_a  = 0;     // first spoke along +X axis (degrees)
eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_d, h = thickness);

        // Hub
        translate([0, 0, -rim_width])
            cylinder(d = hub_d, h = rim_width + 2 * eps);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_a + i * 360 / spoke_count;
            translate([0, 0, -eps])
                linear_extrude(height = thickness + 2 * eps)
                    polygon([
                        [hub_d / 2, 0],
                        [-hub_d / 2, 0],
                        [spoke_w / 2, spoke_w / 2],
                        [spoke_w / 2, -spoke_w / 2]
                    ]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
