// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------- Parameters ----------
thickness      = 5;     // wheel thickness (mm)
outer_d        = 60;    // outer rim diameter (mm)
rim_width      = 5;     // rim width (mm)
hub_d          = 16;    // hub diameter (mm)
axle_d         = 6;     // centre axle hole diameter (mm)
spoke_count    = 8;     // number of spokes
spoke_w        = 4;     // spoke width (mm)
first_spoke_a  = 0;     // first spoke along +X axis (degrees)
eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;

// ---------- Derived ----------
inner_d = outer_d - 2 * rim_width;   // ring inner diameter (bore)
spoke_r_start = hub_d / 2 + 0.6;       // spoke inner radius with overlap
spoke_r_end   = outer_d / 2 - 0.6;     // spoke outer radius with overlap

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_d, h = thickness);

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, first_spoke_a + i * 360 / spoke_count])
                translate([spoke_r_start, 0, 0])
                    cube([spoke_w, spoke_r_end - spoke_r_start + 1, thickness]);
        }
    }

    // Through bore (rim + hub)
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Axle hole (hub)
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
