// T-shaped extrusion nut / spacer - a T cross-section (flange + neck) 20 mm long along X,
// a vertical screw hole through the centre, printed resting on the flange (z = 0 upward).
// NOVEL general part.
//

$fn = 64;

// ---- Dimensions (mm) ----
x_len      = 20;    // part length along X
flange_w   = 10;    // bottom flange width (Y)
flange_t   = 2;     // flange thickness (z = 0 to 2)
neck_w     = 6;     // neck width above flange
neck_top_z = 5;     // top of neck (absolute Z)
screw_d    = 3.4;   // vertical screw hole diameter

eps        = 0.5;   // cutter overshoot past faces

// ---- Model ----
difference() {
    union() {
        // Bottom flange
        translate([-x_len/2, -flange_w/2, 0])
            cube([x_len, flange_w, flange_t]);
        // Centred neck rising from top of flange
        translate([-neck_w/2, -neck_w/2, flange_t])
            cube([neck_w, neck_w, neck_top_z - flange_t]);
    }
    // Vertical screw hole through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top_z + 2*eps);
}
