// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 12;   // Z position of the sphere centre (0, 0, 12)

handle_width        = 8;    // handle width along Y
handle_thickness    = 4;    // handle thickness along Z
handle_x_start      = 10;   // handle start position along X
handle_x_end        = 72;   // handle end position along X

cut_overlap         = 0.5;  // extra length of cutters past faces
$fn                 = 96;   // curve resolution

// Derived
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre;                 // flush with rim
handle_bottom_z   = handle_top_z - handle_thickness;

// ---------------- Model ----------------
difference() {
    union() {
        // Spherical bowl: full sphere, lower half kept by the cut below
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Flat handle
        translate([handle_x_start, -handle_width / 2, handle_bottom_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere, leaving the lower half (z = 0 to 12)
    translate([0, 0, bowl_centre + cut_overlap])
        sphere(r = bowl_outer_radius);

    // Clean up any coplanar faces at the rim
    translate([handle_x_start - 1, -handle_width / 2 - 1, handle_top_z - cut_overlap])
        cube([handle_x_end - handle_x_start + 2, handle_width + 2, cut_overlap]);
}
