difference() {
    union() {
        // Spherical bowl (full sphere)
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Flat handle, centred on y = 0, top face flush with the rim
        translate([handle_x_start, -handle_width / 2, bowl_centre - handle_thickness])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere along the horizontal plane z = rim_z,
    // keeping the lower half (the open bowl). The plane extends past the rim
    // so no faces are coplanar.
    translate([0, 0, rim_z - cut_overlap])
        cube([bowl_outer_radius * 2 + cut_overlap, 100, cut_overlap]);

    // Small solid core along the -Z axis so the bottom touches the bed at z = 0
    translate([0, 0, bowl_centre - inner_radius])
        cylinder(r = inner_radius, h = inner_radius + 0.01);
