        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles, centred on their segments
        for (i = [0 : knuckle_n - 1]) {
            x_c = (i - (knuckle_n - 1)/2) * knuckle_pitch;
            // cylinder axis along X, centred at (x_c, knuckle_y, knuckle_z)
            translate([x_c - knuckle_r, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2*eps, $fn = 96);
        }
    }

    // Pin hole running along X through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x_c = (i - (knuckle_n - 1)/2) * knuckle_pitch;
        translate([x_c - eps, knuckle_y, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = plate_thk + 2*eps + 2, $fn = 96);
    }
}
