knuckle_x = [
    -plate_len / 2 + knuckle_pitch / 2,   // 1st
    0,                                    // 3rd
    plate_len / 2 - knuckle_pitch / 2     // 5th
];

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders
        for (x = knuckle_x)
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
    }

    // Pin bore through every knuckle
    for (x = knuckle_x)
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2 * knuckle_z + pin_overlap + eps);
}
