// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)
total_length   = 130;   // overall specimen length (X)

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
grip_x0        = -total_length/2 + grip_length;   // left grip start X
gauge_x0       = grip_x0 + grip_length;           // gauge start X
gauge_x1       = gauge_x0 + gauge_length;         // gauge end X
right_x0       = gauge_x1 + transition_len;        // right grip start X
right_x1       = right_x0 + grip_length;          // right grip end X

// ---------- Model ----------
difference() {
    // Solid body: grip - transition - gauge - transition - grip
    union() {
        for (x0 = [grip_x0, grip_x0 + grip_length, gauge_x0, gauge_x1, right_x0]) {
            c = x0 < gauge_x0 ? grip_width :
                x0 > gauge_x1 + transition_len ? grip_width :
                gauge_width + 2 * (x0 - gauge_x0) * (grip_width - gauge_width) / transition_len;
            translate([x0, -c/2, 0]) cube([1, c, thickness]);
        }
    }

    // Cut along X, past the end faces
    translate([-total_length/2 - eps, -thickness/2 - eps, 0])
        cube([total_length + 2*eps, thickness + 2*eps, thickness + 2*eps]);
}
