// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
grip_x = grip_length * 2 + gauge_length + transition_len * 4;     // 130 mm check
grip_y = grip_width;
trans_w0 = grip_width;  // transition start width (at grip)
trans_w1 = gauge_width; // transition end width (at gauge)

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_length / 2 + grip_length + transition_len * 2, -grip_y / 2, 0])
            cube([grip_length, grip_y, thickness]);
        translate([ total_length / 2 - grip_length - transition_len * 2, -grip_y / 2, 0])
            cube([grip_length, grip_y, thickness]);
        // Gauge section
        translate([-total_length / 2 + grip_length + transition_len * 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transition sections (linear width change)
        translate([-total_length / 2 + grip_length, -trans_w0 / 2, 0])
            linear_extrude(thickness)
                polygon([[-0, -trans_w0 / 2], [-transition_len, -trans_w1 / 2],
                         [-transition_len, trans_w1 / 2], [0, trans_w0 / 2]]);
        translate([ total_length / 2 - grip_length - transition_len, -trans_w0 / 2, 0])
            linear_extrude(thickness)
                polygon([[0, -trans_w0 / 2], [transition_len, -trans_w1 / 2],
                         [transition_len, trans_w1 / 2], [0, trans_w0 / 2]]);
    }
    // Cutters for clean edges (no coplanar faces)
    translate([-total_length / 2 - eps, -grip_y / 2 - eps, -eps])
        cube([total_length / 2 - grip_length - transition_len * 2 + eps, grip_y + 2 * eps, thickness + 2 * eps]);
    translate([ total_length / 2 - grip_length - transition_len * 2 - eps, -grip_y / 2 - eps, -eps])
        cube([grip_length + transition_len * 2 - total_length / 2 + eps, grip_y + 2 * eps, thickness + 2 * eps]);
    translate([-total_length / 2 + grip_length + transition_len * 2 - eps, -gauge_width / 2 - eps, -eps])
        cube([gauge_length + eps, gauge_width + 2 * eps, thickness + 2 * eps]);
    translate([ total_length / 2 - grip_length - transition_len * 2 + eps, -gauge_width / 2 - eps, -eps])
        cube([gauge_length + eps, gauge_width + 2 * eps, thickness + 2 * eps]);
}
