gauge_x0  = grip_x0 + grip_length + transition_len;  // gauge start X
right_x0  = gauge_x0 + gauge_length + transition_len; // right grip start X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([right_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x1 = grip_x0 + transition_len * s;
            x2 = gauge_x0 + transition_len * s;
            w1 = grip_width;
            w2 = gauge_width;
            translate([x1, -w1/2, 0])
                linear_extrude([transition_len, thickness])
                    polygon([[-1, -1], [-1, 1], [1, 1], [1, -1]]); // trapezoid
        }
    }

    // Cut along X to separate grips from gauge and transitions
    translate([grip_x0 + grip_length - eps, -gauge_width/2 - eps, -eps])
        cube([grip_length + 2*eps, gauge_width + 2*eps, thickness + 2*eps]);

    translate([right_x0 - grip_length + eps, -gauge_width/2 - eps, -eps])
        cube([grip_length + 2*eps, gauge_width + 2*eps, thickness + 2*eps]);
}
