    difference() {
        cylinder(d = outer_d, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = rim_i_d, h = wheel_thickness + 2 * eps);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_thickness + 2 * eps);
    }

