        rotate([0, 0, a])
            translate([rim_i_d / 2 + 0.01, 0, -eps])
                linear_extrude(height = wheel_thickness + 2 * eps)
                    polygon([[0, spoke_d], [spoke_d, spoke_d],
                              [spoke_d, -spoke_d], [0, -spoke_d]]);
