rib_offset     = 25;    // centre of outer rib from nearest plate end

eps            = 0.5;   // overcut for clean boolean differences
$fn            = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_top_z      = plate_thk + rib_h;   // top of ribs (z = 8)
plate_bot_z    = plate_thk;          // top of plate / bottom of ribs (z = 3)
outer_x        = plate_len / 2 - rib_offset;  // X of outer rib centre (-25)
inner_x        = outer_x + rib_pitch;         // X of middle rib centre (0)
check_x        = inner_x + rib_pitch;         // X of right outer rib centre (25)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, standing on the plate
    for (i = [0 : rib_count - 1]) {
        translate([
            i < 2 ? outer_x + i * rib_pitch : check_x - rib_pitch,
            -plate_wid / 2,
            plate_bot_z
        ])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
