// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom touching the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 10;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 10;   // Z position of the sphere centre (0, 0, 10)
bowl_rim_z          = 10;   // height of the bowl rim (lower half kept)
bowl_bottom_z       = 0;    // height of the bowl bottom touching the bed

handle_length       = 82;   // handle runs from x = 8 to x = 90 (8 + 82)
handle_width        = 12;   // handle width along Y
handle_thickness    = 3;    // handle thickness along Z
handle_top_z        = 10;   // top face of handle flush with rim

cut_overlap         = 0.5;  // extra length of the cutting plane past the rim
handle_embed        = 0.01; // small overlap of handle into rim for a clean union

$fn = 96;                   // facet count for curved surfaces

// ---------------- Model ----------------
difference() {
    union() {
        // Spherical bowl (full sphere, lower half kept by the cut below)
        cylinder(r = bowl_outer_radius, h = 2 * bowl_centre, centre = bowl_centre);

        // Flat handle along +X, centred on y = 0
        translate([8, 0, handle_top_z - handle_thickness])
            cube([handle_length, handle_width, handle_thickness]);
    }

