knuckle_hole_d = 2;  // pin hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([-plate_len/2 + i * knuckle_step - knuckle_d/2,
                           knuckle_y - knuckle_d/2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + eps);
            }
        }
    }

    // Through-hole along X axis in every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([-plate_len/2 + i * knuckle_step - knuckle_step/2 - eps,
                       knuckle_y,
                       knuckle_z])
                translate([0, 0, -eps])
                    cylinder(d = knuckle_hole_d, h = plate_thk + 2 * eps);
        }
    }
}
