// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

$fn = 64;

// ---------- Derived ----------
grip_x0 = -total_length/2 + grip_length;      // left grip start X
grip_x1 = total_length/2 - grip_length;       // right grip start X
gauge_x0 = grip_x0 + grip_length + transition_len;  // gauge start X
gauge_x1 = gauge_x0 + gauge_length;               // gauge end X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (linear width change, overbuilt then trimmed)
        for (sx = [-1, 1]) {
            x = sx > 0 ? gauge_x0 : grip_x0 + grip_length;
            w = transition_len/2 + x;
            translate([x - transition_len, -w/2, 0])
                cube([transition_len, w, thickness + 1]);
        }
    }

    // Cut the transition regions cleanly, leaving a sharp gauge/grip boundary
    for (sx = [-1, 1]) {
        x = sx > 0 ? gauge_x0 : grip_x0 + grip_length;
        w = transition_len/2 + x;
        translate([x - transition_len - 0.01, -w/2 - 0.01, 0])
            cube([transition_len + 0.01, w + 0.01, thickness + 1]);
    }
}
