// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
grip_x = grip_length * 2 + gauge_length;  // distance between gauge end and grip start (each side)
x0    = -total_length / 2;               // left end X position

// Width of transition section at offset t from grip end
function trans_w(t) = grip_width + (gauge_width - grip_width) * t / transition_len;

difference() {
    // Solid body
    union() {
        for (s = [-1, 1]) {
            translate([x0 + grip_x * s, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        translate([x0 + grip_x, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        for (s = [-1, 1]) {
            translate([x0 + grip_x * s + grip_length - transition_len,
                       -trans_w(transition_len / 2) / 2, 0])
                cube([transition_len, trans_w(transition_len / 2), thickness]);
        }
    }

    // Cutters along X, past each face
    for (x = [x0, x0 + total_length])
        translate([x, -thickness / 2 - eps, -eps])
            cube([thickness + 2 * eps, total_length - x0 - x, 2 * eps]);
}
