        // Outer rim
        cylinder(d = outer_d, h = thickness);

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_a + i * 360 / spoke_count])
                translate([hub_d / 2, 0, 0])
                    cube([spoke_width, (inner_d - hub_d) / 2 + 1, thickness]);
        }
