// T-shaped extrusion nut - slides into an aluminium extrusion slot
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z)

// ---------------- Parameters ----------------
len     = 20;    // part length along X (mm)
flange_w = 12;   // bottom flange width along Y (mm)
flange_t = 2;    // bottom flange thickness (mm), z = 0 to 2
neck_w   = 8;    // neck width along Y (mm)
neck_h   = 4;    // neck height above flange (mm), z = 2 to 6
screw_d  = 3.4;  // central screw hole diameter (mm)
eps      = 0.5;  // cutter overshoot past faces (mm)

$fn = 64;

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: 12 mm (Y) x 20 mm (X) x 2 mm (Z)
        translate([-len/2, -flange_w/2, 0])
            cube([len, flange_w, flange_t]);

        // Neck centred on the flange, rising to z = 6
        translate([-neck_w/2, -flange_w/2, flange_t])
            cube([neck_w, flange_w + neck_w, neck_h]);
    }

    // Vertical screw hole through the centre of the part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2*eps);
}
