    union() {
        // flange: y = -5 .. 5, z = 0 .. 2.5
        translate([-length/2, -flange_w/2, 0])
            cube([length, flange_w, flange_t]);
        // neck: y = -3.5 .. 3.5, z = 2.5 .. 9 (overlaps flange for a clean union)
        translate([-length/2, -neck_w/2, flange_t])
            cube([length, neck_w, height]);
    }
    // central screw hole
    translate([-length/2 - eps, 0, -eps])
        cube([length + 2*eps, screw_d, height + 2*eps]);
}
