// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 100;   // plate length along X
plate_wid      = 80;    // plate width along Y
plate_thk      = 2;     // plate thickness (z = 0 to 2)

rib_thk        = 3;     // rib thickness along X
rib_h          = 5;     // rib height above plate (z = 2 to 7)
rib_count      = 3;     // number of ribs

rib_pitch      = 25;    // centre-to-centre spacing of ribs
rib_offset     = 25;    // centre of outer rib from nearest plate end

eps            = 0.5;   // cutter overshoot past faces
$fn            = 64;    // curve resolution (set per rules)

// ---------------- Derived ----------------
rib_x = [for (i = [0 : rib_count - 1]) rib_offset + i * rib_pitch];
// check: outer rib centre 25 mm from plate end (100 - 25 = 75)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs standing on the plate top face
    for (x = rib_x)
        translate([x - rib_thk / 2, -plate_wid / 2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
}
