    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running full width along Y
    for (i = [0 : rib_count - 1]) {
        if (i == 0)
            x = first_x;
        else if (i == rib_count - 1)
            x = last_x;
        else
            x = (i - (rib_count - 1)/2) * rib_pitch;

        translate([x - rib_thk/2, -plate_wid/2, plate_topp])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
