// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------- Parameters ----------
bowl_outer_radius   = 12;   // outer radius of the spherical bowl
bowl_wall_thickness = 1.5;  // thickness of the bowl wall
bowl_centre         = 12;   // Z position of the sphere centre (0, 0, 12)
handle_width        = 8;    // handle width along Y
handle_thickness    = 4;    // handle thickness along Z
handle_x_start      = 10.5; // handle start position along X
handle_x_end        = 72;   // handle end position along X
eps                 = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre;  // flush with rim (z = 12)
handle_bottom_z   = handle_top_z - handle_thickness;  // z = 8

// ---------- Model ----------
difference() {
    union() {
        // Spherical bowl (full sphere)
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Flat handle
        translate([handle_x_start, -handle_width / 2, handle_bottom_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the upper half of the bowl above the rim (z > bowl_centre),
    // leaving only the lower half with the rim at z = 12
    translate([0, 0, bowl_centre + eps])
        cylinder(r = bowl_outer_radius + 2 * eps, h = eps);

    // Round the inner bottom of the bowl so it sits cleanly on the bed
    translate([0, 0, -eps])
        cylinder(r = bowl_inner_radius + 2 * eps, h = eps);
}
