                              [grip_length, grip_width/2], [grip_length, -grip_width/2]]);
        }
        translate([x0, -gauge/2, 0])
            linear_extrude(thickness)
                polygon([[0, -gauge/2], [0, gauge/2], [gauge_length, gauge/2], [gauge_length, -gauge/2]]);
    }

    // Cut along X through the gauge section, leaving a 2 mm wall on each side
    translate([-eps, -thickness/2 - eps, x0 + gauge_length/2 - transition_len])
        rotate([-90, 0, 0])
            linear_extrude(thickness + 2*eps)
                cube([gauge_length + 2*transition_len, thickness + 2*eps, 2]);
}
