// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
total_length = 2 * grip_length + gauge_length + 2 * transition_len;   // 130 mm
grip_x0      = -grip_length - transition_len;                         // left grip start X
gauge_x0     = -transition_len;                                       // gauge start X (from left)

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([total_length - grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (width: grip_width -> gauge_width)
        translate([grip_x0 + grip_length, -grip_width / 2, 0])
            linear_extrude(height = thickness)
                polygon([[-grip_width / 2, -grip_width / 2],
                         [-grip_width / 2, grip_width / 2],
                         [gauge_width / 2, grip_width / 2],
                         [gauge_width / 2, -gauge_width / 2]]);

        // Right transition (width: grip_width -> gauge_width)
        translate([total_length - grip_x0 - grip_length, -grip_width / 2, 0])
            linear_extrude(height = thickness)
                polygon([[-grip_width / 2, -grip_width / 2],
                         [-grip_width / 2, grip_width / 2],
                         [gauge_width / 2, grip_width / 2],
                         [gauge_width / 2, -gauge_width / 2]]);
    }

    // Cutters for clean overlaps (no coplanar faces)
    translate([grip_x0 + grip_length - eps, -grip_width / 2 - eps, -eps])
        cube([transition_len + 2 * eps, grip_width + 2 * eps, thickness + 2 * eps]);

    translate([total_length - grip_x0 - grip_length - eps, -grip_width / 2 - eps, -eps])
        cube([transition_len + 2 * eps, grip_width + 2 * eps, thickness + 2 * eps]);
}
